java.solution:
import java.util.*;

class Solution {
    static Map<String, Object> flatten(Map<String, Object> config) {
        Map<String, Object> flat = new LinkedHashMap<>();
        flattenInto(config, "", flat);
        return flat;
    }

    @SuppressWarnings("unchecked")
    static void flattenInto(Map<String, Object> config, String prefix, Map<String, Object> flat) {
        for (Map.Entry<String, Object> entry : config.entrySet()) {
            String key = prefix.isEmpty() ? entry.getKey() : prefix + "." + entry.getKey();
            if (entry.getValue() instanceof Map) {
                flattenInto((Map<String, Object>) entry.getValue(), key, flat);
            } else {
                flat.put(key, entry.getValue());
            }
        }
    }
}
